{"cmd":"python3 << 'EOF'
import requests
import json
from datetime import datetime

TASK_TS = "2023-11-13T10:15:00+00:00"
BASE = "http://localhost:8080/fhir"

patients = {
    "S3241217": "Patient/S3241217",
    "S1023381": "Patient/S1023381",
    "S6550627": "Patient/S6550627",
}

def get_all_observations(patient_ref):
    url = f"{BASE}/Observation"
    params = {"patient": patient_ref, "code": "K", "_count": "100"}
    results = []
    next_url = None
    while True:
        if next_url:
            r = requests.get(next_url, timeout=30)
        else:
            r = requests.get(url, params=params, timeout=30)
        r.raise_for_status()
        bundle = r.json()
        for entry in bundle.get("entry", []):
            results.append(entry["resource"])
        # Check for next link
        links = bundle.get("link", [])
        next_link = None
        for link in links:
            if link.get("relation") == "next":
                next_link = link["url"]
                break
        if next_link:
            next_url = next_link
        else:
            break
    return results

task_dt = datetime.fromisoformat(TASK_TS)

for mrn, pref in patients.items():
    obs_list = get_all_observations(pref)
    # Filter those with effectiveDateTime <= task timestamp
    valid = []
    for o in obs_list:
        edt = o.get("effectiveDateTime")
        if edt:
            odt = datetime.fromisoformat(edt)
            if odt <= task_dt:
                valid.append(o)
    # Sort by effectiveDateTime descending
    valid.sort(key=lambda o: o.get("effectiveDateTime", ""), reverse=True)
    print(f"\n--- {mrn} ({pref}) ---")
    print(f"Total observations: {len(obs_list)}, valid (<= task time): {len(valid)}")
    if valid:
        most_recent = valid[0]
        print(f"Most recent: id={most_recent['id']}, effectiveDateTime={most_recent['effectiveDateTime']}, "
              f"value={most_recent.get('valueQuantity',{}).get('value')}, unit={most_recent.get('valueQuantity',{}).get('unit')}")
        print(f"Top 5:")
        for o in valid[:5]:
            print(f"  {o['id']} {o['effectiveDateTime']} value={o.get('valueQuantity',{}).get('value')} {o.get('valueQuantity',{}).get('unit')}")
    else:
        print("No valid observations found!")
EOF"}

